Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    // Einlesen der Eingabedatei und das zu zählende Wort
    std::string input_file_name, search_word;
    std::cout << "Bitte geben Sie den Dateinamen für die Eingabe ein: ";
    std::getline(std::cin, input_file_name);
    std::cout << "Bitte geben Sie das zu suchende Wort ein: ";
    std::getline(std::cin, search_word);

    // Öffnen der Eingabedatei und Fehlerbehandlung
    std::ifstream input_file(input_file_name);
    if (!input_file) {
        std::cerr << "Fehler: Kann Datei nicht öffnen: " << input_file_name << std::endl;
        return 1;
    }

    // Variablen für Wortzählen und aktuelle Zeile
    size_t word_count = 0;
    std::string current_line;

    // Zeilen für Zeile lesen und Wort zählen
    while (std::getline(input_file, current_line)) {
        // Kleinbuchstaben bringen alle Zeilen auf einheitliches Format
        std::transform(current_line.begin(), current_line.end(), current_line.begin(), ::tolower);

        // Suchen nach dem gesuchten Wort und Zählen
        size_t pos = 0;
        while ((pos = current_line.find(search_word, pos)) != std::string::npos) {
            word_count++;
            pos += search_word.length();
        }
    }

    // Ausgabe des Ergebnisses
    std::cout << "Das Wort \"" << search_word << "\" kommt " << word_count << " mal in der Datei " << input_file_name << " vor." << std::endl;

    // Schließen der Eingabedatei
    input_file.close();

    return 0;
}
```

Das Programm benötigt die folgenden Standardbibliotheken:

